#import <Foundation/Foundation.h>

@interface MathUtil : NSObject
+ (unsigned long)factorial:(unsigned long)n;
@end

@implementation MathUtil
+ (unsigned long)factorial:(unsigned long)n {
    return n <= 1 ? 1 : n * [self factorial:n - 1];
}
@end

int main(void) {
    @autoreleasepool {
        printf("%lu\n", [MathUtil factorial:10]);
    }
    return 0;
}

