    @autoreleasepool {
        for (int i = 1; i <= 15; i++) {
            NSMutableString *s = [NSMutableString string];
            if (i % 3 == 0) [s appendString:@"Fizz"];
            if (i % 5 == 0) [s appendString:@"Buzz"];
