#import <Foundation/Foundation.h>

int main(void) {
    @autoreleasepool {
        NSMutableArray *nums = [NSMutableArray array];
        for (int i = 1; i <= 10; i++) [nums addObject:@(i)];

        NSIndexSet *evens = [nums indexesOfObjectsPassingTest:
            ^BOOL(NSNumber *n, NSUInteger idx, BOOL *stop) { return [n intValue] % 2 == 0; }];

        NSMutableArray *squares = [NSMutableArray array];
        [[nums objectsAtIndexes:evens] enumerateObjectsUsingBlock:
            ^(NSNumber *n, NSUInteger idx, BOOL *stop) {
                [squares addObject:@([n intValue] * [n intValue])];
            }];

        printf("%s\n", [[squares componentsJoinedByString:@" "] UTF8String]);
    }
    return 0;
}

