#import <Foundation/Foundation.h>

@protocol Shape <NSObject>
- (NSString *)name;
- (int)area;
@end

@interface Rectangle : NSObject <Shape> { int width, height; }
- (instancetype)initWithWidth:(int)w height:(int)h;
@end

@implementation Rectangle
- (instancetype)initWithWidth:(int)w height:(int)h {
    if ((self = [super init])) { width = w; height = h; }
    return self;
}
- (NSString *)name { return @"Rectangle"; }
- (int)area { return width * height; }
@end

@interface Triangle : NSObject <Shape> { int base, height; }
- (instancetype)initWithBase:(int)b height:(int)h;
@end

@implementation Triangle
- (instancetype)initWithBase:(int)b height:(int)h {
    if ((self = [super init])) { base = b; height = h; }
    return self;
}
- (NSString *)name { return @"Triangle"; }
- (int)area { return base * height / 2; }
@end

int main(void) {
    @autoreleasepool {
        NSArray *shapes = @[[[Rectangle alloc] initWithWidth:3 height:4],
                            [[Triangle alloc] initWithBase:10 height:3]];
        for (id<Shape> s in shapes)
            printf("%s: %d\n", [[s name] UTF8String], [s area]);
    }
    return 0;
}

