#import <Foundation/Foundation.h>

// A category adds methods to an existing class -- even Foundation's NSString.
@interface NSString (Shouting)
- (NSString *)shout;
@end

@implementation NSString (Shouting)
- (NSString *)shout { return [[self uppercaseString] stringByAppendingString:@"!"]; }
@end

int main(void) {
    @autoreleasepool {
        NSString *s = @"hello";
        printf("%s\n", [[s shout] UTF8String]);

        // Selectors are values; the receiver decides at run time what a message means.
        SEL sel = NSSelectorFromString(@"shout");
        printf("%s\n", [[s performSelector:sel] UTF8String]);
        printf("NSNumber responds to shout? %s\n", [@42 respondsToSelector:sel] ? "YES" : "NO");

        // Messaging nil is legal: it does nothing and returns nil / 0.
        NSString *nothing = nil;
        printf("length of [nil shout]: %lu\n", (unsigned long)[[nothing shout] length]);
    }
    return 0;
}
